"""Restore service, material and article sections from the prior project source."""
import json

def render(api):
    data=json.loads((api['DATA']/'editorial.json').read_text())
    esc,link,write,template,intro,card,checklist=[api[k] for k in ['esc','link','write','template','section_intro','card','checklist']]
    for group,label in [('services','Услуги производства упаковки'),('materials','Материалы для упаковки')]:
        items=data[group]
        body=intro(label,'Выберите технологию или материал для обсуждения вашего проекта.')
        body+='<section class="section"><div class="wrap cardgrid">'+''.join(card(n,p,'Технология' if group=='services' else 'Материал',d) for n,p,d in items)+'</div></section>'
        write('/'+group+'/',template('/'+group+'/',label+' | Россантпак',label+'. Подготовка технического задания и запрос расчёта.',label,body))
        for name,path,desc in items:
            body=intro(name,desc)
            body+=f'''<section class="section"><div class="wrap prose"><h2>{esc(name)}: параметры проекта</h2>
<p>{esc(desc)} Подбор начинается с назначения детали, её размеров и условий эксплуатации. В техническом задании нужно указать материал, толщину, количество и требования к внешнему виду. Если готовая деталь работает в составе упаковки, передайте размеры соседних элементов и порядок сборки.</p>
<h3>Чертёж, макет и исходный материал</h3><p>Чертёж должен содержать размеры, единицы измерения и обозначение участков, для которых важна точность. Для декоративного оформления дополнительно согласуют макет и образец цвета. Возможность обработки конкретного материала уточняют до размещения заказа.</p>
<h2>Согласование результата: {esc(name.lower())}</h2><p>До выпуска партии определите, как будете оценивать результат: по размерам, посадке в изделие, качеству кромки, соединению слоёв или оформлению. Если требуется испытание или подтверждение особых свойств, укажите это отдельно. Образец помогает обнаружить несоответствие конструкции до тиражирования.</p>
<h3>Что влияет на расчёт</h3><p>Количество операций, расход материала, сложность контура, подготовка оснастки и тираж рассматриваются совместно. Для сравнения вариантов используйте одинаковые исходные требования. Итоговые условия фиксируют после рассмотрения технического задания.</p>
<p>Посмотрите <a href="{link('/product/')}">каталог упаковочных решений</a>, чтобы выбрать близкий пример. Подготовленный чертёж и параметры можно включить в <a href="{link('/request/')}">запрос расчёта</a>.</p></div></section>'''+checklist(name)
            write(path,template(path,name+' на заказ | Россантпак',desc+' Расчёт по чертежу и согласованным требованиям.',name,body,[('Главная','/'),(label,'/'+group+'/')]))
    articles=data['articles']
    body=intro('Статьи об упаковке','Материалы для выбора конструкции, подготовки чертежей и согласования заказа.')
    body+='<section class="section"><div class="wrap cardgrid">'+''.join(card(n,p,'Руководство',d) for n,p,d,*_ in articles)+'</div></section>'
    write('/articles/',template('/articles/','Статьи об упаковке и подготовке заказа | Россантпак','Выбор материала, защита хрупких изделий и подготовка технического задания на упаковку.','Статьи об упаковке',body))
    related=['/product/lozhementy/','/product/korobki/','/manufacture/','/product/purpose/upakovka-dlya-khrupkogo7733/','/product/plastikovaya-upakovka/vakuumnaya-formovka/','/product/korobki/korobki-s-lozhementom/']
    for (name,path,desc,a,b,c),target in zip(articles,related):
        body=intro(name,desc)+f'''<section class="section"><article class="wrap prose"><h2>{esc(name)}: исходная задача</h2><p>{esc(a)}</p><p>Зафиксируйте состав комплекта и сценарий применения. Упаковка для многократного использования, подарка и разовой перевозки может иметь разные требования к открыванию, прочности и оформлению. Без этих исходных данных сравнение только по внешнему размеру будет неполным.</p><h2>Конструкция и согласование образца</h2><p>{esc(b)}</p><h3>Размеры и допуски</h3><p>Различайте размеры изделия, внутреннее пространство и наружные габариты упаковки. Учитывайте выступы, разъёмы, ручки и детали, на которые нельзя опираться. При наличии нескольких предметов укажите положение каждого и порядок извлечения.</p><h3>Проверка в сборе</h3><p>Оцените, легко ли укладывается изделие, не смещается ли оно внутри и закрывается ли коробка. Если нужны определённые защитные свойства, задайте условия проверки и критерии приемки. Название материала не заменяет испытаний готовой конструкции.</p><h2>Подготовка запроса производителю</h2><p>{esc(c)}</p><p>Добавьте фотографии с масштабом, чертежи и требования к оформлению. Укажите объём партии и необходимую дату получения, чтобы производитель мог оценить задачу и согласовать условия. Если выбираете между несколькими решениями, сравнивайте их при одинаковой комплектации.</p><p>Подходящие примеры представлены в <a href="{link(target)}">профильном разделе каталога</a>. Чтобы обсудить исполнение, <a href="{link('/request/')}">подготовьте запрос на расчёт</a>.</p></article></section>'''
        schema={'@context':'https://schema.org','@type':'Article','headline':name,'description':desc,'url':api['DOMAIN']+path,'publisher':{'@type':'Organization','name':'Россантпак'}}
        write(path,template(path,name+' | Россантпак',desc,name,body,[('Главная','/'),('Статьи','/articles/')],schema,kind='article'))
